problem.starterCode:
int a = 5;
int b = a++;
System.out.println("a: " + a + ", b: " + b);

a = 5;
b = ++a;
System.out.println("a: " + a + ", b: " + b);

problem.solution:
int a = 5;
int b = a++; // b=5, a=6
System.out.println("a: 6, b: 5");

a = 5;
b = ++a; // a=6, b=6
System.out.println("a: 6, b: 6");
